/* ---------- language packs: template for translators and import ---------- */
/** 'label:group.key' → [group, key] (the key may be empty) */
const labKey = (key) => { const s = key.slice(6); const i = s.indexOf('.'); return i < 0 ? [s, ''] : [s.slice(0, i), s.slice(i + 1)]; };
const LANGX = {
  /** every key of a domain: from the code (build) + source pack + all packs */
  allKeys(d) {
    d = I18N.dom(d); const set = new Set(I18N.keys[d] || []);
    for (const pk of Object.values(I18N.packs[d])) for (const k of Object.keys(pk.strings)) set.add(k);
    return [...set];
  },
  labelRows(d) {
    d = I18N.dom(d); const src = (I18N.packs[d][I18N.src[d]] || {}).labels || {}; const out = [];
    for (const [g, m] of Object.entries(src)) for (const k of Object.keys(m)) out.push(['label:' + g + '.' + k, m[k]]);
    return out;
  },
  /** .xlsx: one row per key — key · source · existing languages · column to fill */
  async template(d, target) {
    d = I18N.dom(d); const packs = I18N.list(d).filter(p => p.code !== I18N.src[d]);
    const wb = new XLSXW.Workbook(); wb.title = 'Inregelaar language pack';
    const ws = wb.sheet('Translations'); ws.landscape = true;
    const H = { font: { b: true, sz: 9, color: 'FFFFFF' }, fill: '262157', align: { v: 'center', wrap: true } };
    const K = { font: { sz: 7.5, color: '888888' }, align: { v: 'top', wrap: true } }, S0 = { font: { sz: 9 }, align: { v: 'top', wrap: true } };
    const IN = { font: { sz: 9, color: '0000FF', b: true }, fill: 'FFF8E1', border: { all: true, color: 'CFCFD8' }, align: { v: 'top', wrap: true } };
    const tcode = (target || '').toLowerCase();
    const meta = [['domain', d], ['code', tcode || 'xx'], ['name', tcode && I18N.packs[d][tcode] ? I18N.packs[d][tcode].name : 'Language name'], ['locale', tcode || 'xx-BE']];
    ws.set(1, 1, 'Ventilation Setup Tool — ' + (d === 'ui' ? 'interface' : 'report') + ' language pack. Fill in the cream column; keep {placeholders}. Import: Settings → Languages → Import pack.', { font: { b: true, sz: 10, color: '262157' } });
    ws.merge(1, 1, 1, 4 + packs.length);
    meta.forEach(([k, v], i) => { ws.set(2 + i, 1, k, K); ws.set(2 + i, 2, v, IN); });
    const hr = 7; const cols = ['key', I18N.src[d] + ' (source)', ...packs.map(p => p.code), 'translation'];
    cols.forEach((h, i) => ws.set(hr, i + 1, h, H)); ws.freeze = { r: hr + 1, c: 3 };
    [34, 48, ...packs.map(() => 40), 48].forEach((w, i) => ws.width(i + 1, w));
    const rows = [...this.labelRows(d), ...this.allKeys(d).map(k => [k, (I18N.packs[d][I18N.src[d]] || { strings: {} }).strings[k] ?? k])];
    let r = hr + 1;
    for (const [key, src] of rows) {
      const isLab = key.startsWith('label:'); const [g, k] = isLab ? labKey(key) : [];
      const val = (pk) => { const v = isLab ? (pk.labels[g] || {})[k] : pk.strings[key]; return v == null ? '' : typeof v === 'object' ? JSON.stringify(v) : String(v); };
      ws.set(r, 1, key, K); ws.set(r, 2, typeof src === 'object' ? JSON.stringify(src) : String(src), S0);
      packs.forEach((pk, i) => ws.set(r, 3 + i, val(pk), S0));
      ws.set(r, 3 + packs.length, tcode && I18N.packs[d][tcode] ? val(I18N.packs[d][tcode]) : '', IN); r++;
    }
    return wb.blob();
  },
  /** read a pack from .json or .xlsx (template above) */
  async read(file) {
    if (/\.json$/i.test(file.name) || /json/.test(file.type)) { const o = JSON.parse(await file.text()); if (o.strings || o.labels) return o; throw new Error('format'); }
    const sheets = await XLSXR.read(await file.arrayBuffer()); const sh = sheets.find(s => /translation/i.test(s.name)) || sheets[0];
    const meta = {}; let hr = -1;
    for (let i = 0; i < Math.min(sh.rows.length, 30); i++) { const row = sh.rows[i] || []; const k = String(row[0] ?? '').trim(); if (k === 'key') { hr = i; break; } if (['domain', 'code', 'name', 'locale'].includes(k)) meta[k] = String(row[1] ?? '').trim(); }
    if (hr < 0) throw new Error('format');
    const head = sh.rows[hr].map(x => String(x ?? '').trim()); const tc = head.lastIndexOf('translation') >= 0 ? head.lastIndexOf('translation') : head.length - 1;
    const pack = { domain: meta.domain || 'ui', code: meta.code, name: meta.name, locale: meta.locale, labels: {}, strings: {} };
    for (let i = hr + 1; i < sh.rows.length; i++) {
      const row = sh.rows[i] || []; const key = row[0] == null ? '' : String(row[0]); let v = row[tc]; if (!key || v == null || String(v).trim() === '') continue;
      v = String(v); if (/^\{"(one|few|many|other)"/.test(v)) { try { v = JSON.parse(v); } catch (e) { } }
      if (key.startsWith('label:')) { const [g, k] = labKey(key); (pack.labels[g] = pack.labels[g] || {})[k] = v; } else pack.strings[key] = v;
    }
    return pack;
  },
  /** coverage of a pack: share of keys translated */
  coverage(d, code) {
    d = I18N.dom(d); const pk = I18N.packs[d][code]; if (!pk) return 0; if (code === I18N.src[d]) return 1;
    const keys = this.allKeys(d); const labs = this.labelRows(d); const tot = keys.length + labs.length; if (!tot) return 1;
    let n = 0; for (const k of keys) if (pk.strings[k] != null) n++;
    for (const [key] of labs) { const [g, k] = labKey(key); if ((pk.labels[g] || {})[k] != null) n++; }
    return n / tot;
  },
};
